const json=(statusCode,data)=>({statusCode,headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
async function verify(event){const token=(event.headers.authorization||event.headers.Authorization||'').replace(/^Bearer\s+/i,'');if(!token)throw new Error('Unauthorized');const r=await fetch(`${process.env.URL}/.netlify/identity/user`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)throw new Error('Unauthorized');return r.json()}
async function rest(url,key,path){const r=await fetch(`${url}/rest/v1/${path}`,{headers:{apikey:key,Authorization:`Bearer ${key}`}});const t=await r.text();if(!r.ok)throw new Error(t);return t?JSON.parse(t):null}
exports.handler=async event=>{try{if(event.httpMethod!=='POST')return json(405,{error:'Method not allowed'});const user=await verify(event),{site_id,filename,type,contentBase64}=JSON.parse(event.body||'{}'),url=process.env.SUPABASE_URL,key=process.env.SUPABASE_SERVICE_ROLE_KEY,bucket=process.env.SUPABASE_MEDIA_BUCKET||'studio-media';if(!url||!key)throw new Error('Supabase environment variables are not configured.');if(!site_id)throw new Error('Choose a website first.');const sites=await rest(url,key,`sites?select=id,created_by&id=eq.${encodeURIComponent(site_id)}&limit=1`);if(!sites?.length)throw new Error('Site not found.');if(sites[0].created_by!==user.email){const m=await rest(url,key,`site_members?select=role&site_id=eq.${encodeURIComponent(site_id)}&email=ilike.${encodeURIComponent(String(user.email||'').toLowerCase())}&limit=1`);if(!m?.length)throw new Error('You do not have access to this site.')}const safe=(filename||'file').replace(/[^a-zA-Z0-9._-]/g,'-'),path=`${site_id}/${new Date().toISOString().slice(0,10)}/${Date.now()}-${safe}`,bytes=Buffer.from(contentBase64,'base64');const up=await fetch(`${url}/storage/v1/object/${bucket}/${path}`,{method:'POST',headers:{apikey:key,Authorization:`Bearer ${key}`,'Content-Type':type||'application/octet-stream','x-upsert':'false'},body:bytes});if(!up.ok)throw new Error(await up.text());const public_url=`${url}/storage/v1/object/public/${bucket}/${path}`;const rec=await fetch(`${url}/rest/v1/media_assets`,{method:'POST',headers:{apikey:key,Authorization:`Bearer ${key}`,'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify({site_id,filename:safe,storage_path:path,public_url,mime_type:type||'',size_bytes:bytes.length,uploaded_by:user.email})});if(!rec.ok)throw new Error(await rec.text());return json(200,{...(await rec.json())[0],public_url})}catch(e){return json(e.message==='Unauthorized'?401:500,{error:e.message})}}
